### Option (a): Menu Selection Using `switch` Statement
```javascript
let option = Number(prompt("Enter menu option number (1-4):"));
switch (option) {
    case 1:
        document.write("Add Record");
        break;
    case 2:
        document.write("Update Record");
        break;
    case 3:
        document.write("Delete Record");
        break;
    case 4:
        document.write("View Record");
        break;
    default:
        document.write("Invalid Option Selected");
}
```

### Option (b): Student Total & Average Marks Using `for` Loop
```javascript
let n = Number(prompt("Enter the number of students:"));
if (n < 1) {
    document.write("Invalid number of students");
} else {
    let total = 0;
    for (let i = 1; i <= n; i++) {
        let marks = Number(prompt("Enter marks for student " + i + ":"));
        total += marks;
    }
    let average = total / n;
    document.write("Total Marks: " + total + "<br>");
    document.write("Average Marks: " + average);
}
```
